edits.old:
$indexNames = @('scripts/character_roster.gd','scripts/exact_vertex_indexer.gd')
if ($pins.index_overlay.Count -ne 2 -or @($pins.index_overlay.Keys | Where-Object { $_ -notin $indexNames }).Count -ne 0) { throw 'Only two accepted indexing files are allowed.' }
foreach ($relative in $indexNames) {
    $indexSourcePath = Assert-Within $PSScriptRoot (Join-Path $PSScriptRoot ('index/'+$relative))
    $bytes = [IO.File]::ReadAllBytes($indexSourcePath)
    if ((Get-ByteSha $bytes) -ne $pins.index_overlay[$relative]) { throw "Index overlay changed: $relative" }
    if ($Variant -eq 'indexed') { [IO.File]::WriteAllBytes((Assert-Within $project (Join-Path $project $relative)),$bytes) }
}

edits.new:
$queryNames = @('scripts/world_adapter.gd','tests/test_world_adapter.gd','tests/test_actor_navigation.gd','tests/fixtures/query_resource_candidate.gd','tests/fixtures/query_resource_reference.gd')
if ($pins.query_overlay.Count -ne 5 -or @($pins.query_overlay.Keys | Where-Object { $_ -notin $queryNames }).Count -ne 0) { throw 'Only five centrally tested query-resource files are allowed.' }
foreach ($relative in $queryNames) {
    $candidatePath = Assert-Within $PSScriptRoot (Join-Path $PSScriptRoot ('query/'+$relative))
    $bytes = [IO.File]::ReadAllBytes($candidatePath)
    if ((Get-ByteSha $bytes) -ne $pins.query_overlay[$relative]) { throw "Query overlay changed: $relative" }
    if ($Variant -eq 'query_resource') {
        $destination = Assert-Within $project (Join-Path $project $relative)
        $null = New-Item -ItemType Directory -Path ([IO.Path]::GetDirectoryName($destination)) -Force
        [IO.File]::WriteAllBytes($destination,$bytes)
    }
}

foreach ($relative in $pins.central_proof.Keys) {
    $path = Assert-Within $repoRoot (Join-Path $repoRoot $relative)
    if ((Get-Sha $path) -ne $pins.central_proof[$relative]) { throw "Central proof input changed: $relative" }
}
$wrapperHash = Get-Sha $PSCommandPath
